export function deepMerge(a, b) {
  const out = { ...a };
  for (const k of Object.keys(b)) {
    const av = out[k], bv = b[k];
    if (av && bv && typeof av === "object" && typeof bv === "object") out[k] = deepMerge(av, bv);
    else out[k] = bv;
  }
  return out;
}
